  'Elke afbeelding, grafiek, video en audio heeft een beschrijving nodig voor schermlezers en bijsluiters.':
      'Quaeque imago, diagramma, pellicula et audio descriptione indiget pro lectoribus schematis et libellis.',
  'Verwijzingen naar afbeeldingen, video en audio worden gecontroleerd op een bestaand bestand in het project.':
      'Relationes ad imagines, pelliculam et audio verificantur num fasciculus exsistens in proiecto sit.',
  'Aantal en lengte van bullets, woorden, nesting, kolombalans en de dichtheid van quotes, titels, tabellen en code zodat alles leesbaar past.':
      'Numerus et longitudo punctorum, verborum, nidificationis, aequilibrium columnarum et densitas citationum, titulorum, tabularum et codicis ut omnia legibiliter apta sint.',
  'Bodytekst met contrast onder {crit}:1 telt als fout; daarboven tot de AA-norm als waarschuwing.':
      'Textus corporis cum contrarietate infra {crit}:1 ut error numeratur; supra id usque ad normam AA ut admonitio.',
