  'https://app.voorbeeld/login': 'https://app.example/login',
  'Deze afbeelding naar het AI-model sturen?':
      'Hanc imaginem ad exemplar IA mittere?',
  'De afbeelding gaat ongewijzigd naar': 'Imago immutata mittetur ad',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'OciDeck nihil in imagine obliterat: vultus, textus in imagine capta et data conspicua una mittuntur.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'Examen imaginum hic unum vel plures vultus agnoscibiles invenit.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Iuxta exportationem duo documenta ponuntur quibus accipiens obliterationes examinare potest.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'enumerat quae omissa sint, sine ipsis valoribus. Hoc documentum cum relatione mitti licet.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'claves continet quibus omnis valor obliteratus retro computari potest. Noli hoc documentum una mittere: ita obliteratio irrita fit. Apud fontem id serva.',
  'slides': 'diapositivae',
  'Achtergehouden': 'Retentum',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Retentum: severius quam praesentatio classificatum',
  '1 slide achtergehouden door haar TLP': '1 scida propter TLP suum retenta',
  'slides achtergehouden door hun TLP': 'scidae propter TLP suum retentae',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Hae scidae in praesentatione, exportatione et fasciculo omittuntur. Gradum TLP praesentationis in Informatione praesentationis auge ut includantur.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Omnes paginae classificatione TLP sua retinentur, itaque nihil est quod ostendatur.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Omnes paginae classificatione TLP sua retinentur, itaque nihil est quod exportetur.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Omnes paginae praetermittuntur aut classificatione TLP sua retinentur, itaque nihil est quod ostendatur.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Omnes paginae praetermittuntur aut classificatione TLP sua retinentur, itaque nihil est quod exportetur.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Numeri diagrammatis servati non sunt — in hac fenestra tantum manent:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'In navigatro nulla est recuperatio post ruinam: si hanc tabellam claudis, opus non servatum perit. Praesentationem tuam ipse serva.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  Basis datorum CVE localis (descensum ipse incipis): OciDeck data cumulata per api.github.com petit et per plagulam emissionis quam illa inscriptio monstrat.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Inquisitio CVE (praedefinite exstincta): si accensa est, verbum quaesitum ad speculum CVE constitutum mittitur et, si nihil invenit, ad basim datorum Europaeam ENISA et ad MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Pellicula YouTube vel Vimeo inserta lusorem ab illo ministerio onerat.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  In navigatro: si navigatrum inscriptionem directe petere recusat, OciDeck per servitorem unde applicatio venit iterum conatur; illa inscriptio tunc ad illum servitorem pervenit.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Retractio non servata est. Cum rursus incohabis, consensus tuus iterum valebit.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Titulus partis qui novam praesentationis partem nuntiat. Brevem serva. Ex bibliotheca imaginum imaginem fundi adde.',
  'Bronnen doorzoeken…': 'Fontes perscrutans…',
  'Niet doorzocht': 'Non perscrutatum',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Haec inspectio in versione interretiali non decurrit: agnitio vultuum bibliothecam systematis requirit quam navigatrum non habet. Versione mensali utere ad vultus in imaginibus inspiciendos.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Signum lectionis et scriptionis iura in repositorio requirit. Gitea et Forgejo quaestionem in servo non habent; OciDeck localiter quaerit.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Signum ambitum repo requirit (vel subtiliter: Contents legere et scribere).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Signum read_repository, write_repository et read_api requirit. Quaestio in servo Advanced vel Exact Search poscit.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Inquisitio celeris in servo — propter moram indicis, fasciculus modo mutatus deesse potest.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Media in simplici .md tabella non servantur',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Imagines, pellicula et sonus quos in hac tabella elegisti in memoria tantum vivunt. Simplex tabella .md eos non servat — reserata absunt. Exporta ut fasciculum .ocideck ut media tecum feras.',
