  'Vorige rapportage': 'Relatio prior',
  'Een scorecard toont hoogstens vijf cijfers; meer leest niet meer als een oordeel.':
      'Tabula numerorum ad summum quinque numeros ostendit; plures iam non ut iudicium leguntur.',
  'Laat de vorige rapportage leeg als er nog geen meting was; de slide toont dan geen verandering.':
      'Relationem priorem vacuam relinque si mensura nondum fuit; tabula tum nullam mutationem ostendet.',
  'Bepaalt of een stijging groen of rood kleurt. De pijl volgt altijd de cijfers.':
      'Statuit utrum incrementum viride an rubrum sit. Sagitta semper numeros sequitur.',
  'Een paar kerncijfers met het cijfer van de vorige rapportage ernaast, zodat de verandering het verhaal vertelt. Geef per cijfer aan of stijgen goed of slecht nieuws is.':
      'Pauci numeri praecipui cum numero relationis prioris iuxta positi, ut mutatio narret. Pro quoque indica utrum incrementum bonum an malum nuntium sit.',
  'Zekere vondsten als fout behandelen': 'Inventa certa ut errores tractare',
  'Normaal is een zekere vondst — een BSN, een IBAN, een e-mailadres — een waarschuwing die je kunt negeren. Aan maakt er een fout van, en dan kan de export erop blokkeren als je die instelling ook aan hebt staan. Bedoeld voor omgevingen waar zulke gegevens er echt niet doorheen mogen. Onzekere vondsten blijven een waarschuwing.':
      'Plerumque inventum certum — numerus civilis, IBAN, inscriptio electronica — monitum est quod neglegere potes. Accensum errorem ex eo facit, et tunc exportatio in eo obstare potest si etiam illam optionem accensam habes. Destinatum locis ubi talia data vere transire non licet. Inventa incerta monitum manent.',
  'Medicare-nummer — een zorggegeven': 'numerus Medicare — datum salutis',
  'bedrijfsnummer': 'numerus societatis',
  'zorgverzekeringsnummer (RAMQ) — een zorggegeven':
      'numerus assecurationis sanitatis (RAMQ) — datum salutis',
  'zorgverzekeringsnummer (OHIP) — een zorggegeven':
      'numerus assecurationis sanitatis (OHIP) — datum salutis',
  'bedrijfsnummer (BN)': 'numerus negotii (BN)',
  'zorgverlenersnummer (NPI)': 'numerus curatoris valetudinis (NPI)',
  'Medicare-nummer (MBI) — een zorggegeven':
      'numerus Medicare (MBI) — datum valetudinis',
  'wacht op verbinding': 'nexum exspectat',
  'Opgeslagen op deze computer, nog niet in de repository. Gaat mee zodra er weer verbinding is — of nu, met "Wachtrij legen".':
      'In hoc computatro servatum, nondum in promptuario. Ibit simulac nexus redierit — vel nunc, per "Ordinem vacuare".',
  'Branch (optioneel)': 'Ramus (optativus)',
  'let op: de standaardbranch is': 'cave: ramus praedefinitus est',
  'jij werkt op': 'tu in eo laboras',
  'werkgeversnummer (EIN)': 'numerus conductoris (EIN)',
  'laatste vier cijfers van een SSN': 'quattuor ultimae notae SSN',
  'geboortedatum, postcode en geslacht samen — die drie wijzen meestal één persoon aan, ook zonder naam':
      'dies natalis, numerus postalis et sexus simul — haec tria plerumque unam personam designant, etiam sine nomine',
  'Het certificaat van deze server wordt niet vertrouwd. Bij een zelf gehoste server kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Testimonium huius servitoris non creditur. In servitoris proprio id inspicere et ei credere potes apud Optiones → Repositorium.',
  'Het certificaat van de forge wordt niet vertrouwd. Bij een zelf gehoste forge kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Testimonium huius forge non creditur. In forge proprio id inspicere et ei credere potes apud Optiones → Repositorium.',
  'Het certificaat van het endpoint wordt niet vertrouwd. Bij een zelf gehost endpoint kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Testimonium huius endpoint non creditur. In endpoint proprio id inspicere et ei credere potes apud Optiones → Repositorium.',
  'Het certificaat van de forge wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'Testimonium forge non creditur — a se signatum, exspiratum, vel alii nomini datum.',
  'Het certificaat van het endpoint wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'Testimonium endpoint non creditur — a se signatum, exspiratum, vel alii nomini datum.',
  'creditcardnummer': 'numerus chartae creditoriae',
  'beveiligingscode van een creditcard': 'codex securitatis chartae',
  'gegevens in de sprekersnotities — onzichtbaar op de slide, wél in de export':
      'data in notis oratoris — in tabella invisibilia, sed in exportatione praesentia',
  'Certificaat vertrouwen?': 'Huic testimonio credere?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'Testimonium huius servitoris ab editore agnito signatum non est. Id in servitore proprio usitatum est, sed etiam nexus interceptus talis apparet.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Vestigium infra cum eo quod servitor tuus ipse ostendit compara. Si congruunt, cum recta machina loqueris.',
  'Uitgegeven aan': 'Datum ad',
  'Uitgegeven door': 'Datum ab',
  'Geldig tot': 'Validum usque ad',
  'Vingerafdruk (SHA-256)': 'Vestigium (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Huic uni testimonio tantum creditur. Si servitor id postea mutabit, OciDeck iterum rogabit.',
  'Vertrouwen': 'Credere',
  'Certificaat bekijken': 'Testimonium inspicere',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Loci ubi exhibitiones tuas servas et perscrutaris — scrinia in hoc computatro, servi WebDAV, vasa S3 et promptuaria git permixta. Trahe ea in ordinem quem vis: summum cuiusque generis pro consueto valet.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  Repositorium S3: cum ad vas te coniungis, terminus, nomen vasis et clavis tua accessus servantur (clavis secreta tuto in clavario systematis tui) et exhibitiones quas aperis vel servas ad illud repositorium mittuntur.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Repositorium Git: cum ad promptuarium te coniungis, tessera tua accessus servatur (tuto in clavario systematis tui) et exhibitiones quas servas ad illum servum tamquam commissa mittuntur. Exemplar operis promptuarii sine cifris in hoc instrumento manet.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Nomina morborum huic linguae desunt. Religio, opinio politica et vocabula collegiorum opificum agnoscuntur, et formae cum numero probationis (BSN, IBAN, diploma) semper valent — sed noli confidere diagnosin inventum iri.',
  'niet getest': 'non probatum',
  'Werkte op': 'Valuit die',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Admissus es, sed hic aditum non habes. Tessera tua non est impedimentum — administratorem de iuribus in hac plica roga.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Signum tuum validum est, sed hoc facere non licet. Plura iura ei da, vel exspecta si officina modum imponit.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'Signum validum est, sed hoc facere non licet — plura iura in promptuario ei da.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Admissus, sed sine aditu — tessera tua non est impedimentum. Iura in hac plica pete.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Hoc URL DAV plenum videtur. Apud Nextcloud OciDeck illam viam ipse derivat — hic solus servitor pertinet.',
  'Overnemen': 'Adhibe',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'WebDAV non recte constitutum est — data servitoris apud Optiones → Repositorium inspice.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'Promptuarium git non recte constitutum est — servitorem, dominum et promptuarium apud Optiones → Repositorium inspice.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'Nomen servitoris officinae non exstat, vel inveniri non potest. URL servitoris de mendo typographico inspice.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Haec officina inscriptionem privatam vel LAN habet. Eam ut internam fidam nota apud Optiones → Repositorium.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'Officina adiri non potest — nexum tuum et URL servitoris inspice.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'Aditus ad officinam defecit. Signum tuum inspice: ius legendi promptuarium requirit, et ius scribendi ut servet.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'In promptuario non inventum — vel signum tuum id videre non licet.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'Officina errorem reddidit. Postea itera.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
      'Haec inscriptio non ut officina respondet. Rectumne est genus officinae apud Optiones → Repositorium?',
  'Stel eerst een WebDAV-server in bij Instellingen → Opslag.':
      'Servitorem WebDAV primum apud Optiones → Repositorium constitue.',
  'Nodig wanneer de forge op een privé- of thuisnetwerk draait. Zonder deze vlag weigert de beveiliging een privé-adres.':
      'Necessarium cum officina in rete privata vel domestica currit. Sine hoc signo custodia securitatis inscriptionem privatam respuit.',
  'Vul server-URL, eigenaar en repository in':
      'URL servitoris, dominum et promptuarium comple',
  'de standaardbranch heet': 'ramus praedefinitus vocatur',
  'die wordt voortaan gebruikt': 'is posthac adhibebitur',
  'de repository is nog leeg; de eerste opslag vult hem':
      'promptuarium adhuc vacuum est; prima servatio id implebit',
  'let op: dit token mag alleen lezen, dus opslaan zal mislukken':
      'cave: hoc signum tantum legere potest, ergo servatio deficiet',
  'Aanmelden mislukt — controleer het token. Het heeft leesrechten op de repository nodig, en schrijfrechten om te kunnen opslaan.':
      'Aditus defecit — signum inspice. Ius legendi promptuarium requirit, et ius scribendi ut servare possis.',
  'Repository niet gevonden — of je token mag hem niet zien. Controleer eigenaar en repositorynaam.':
      'Promptuarium non inventum — vel signum tuum id videre non licet. Dominum et nomen promptuarii inspice.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge die je hebt gekozen?':
      'Haec inscriptio non ut officina respondet. Rectumne est genus officinae quod elegisti?',
  'kenteken': 'numerus vehiculi',
  'Voor de taal van dit deck is er geen trefwoordenlijst voor bijzondere persoonsgegevens. Patronen met een controlegetal (BSN, IBAN, paspoort) werken wel; woorden als "diagnose" of "verdachte" worden niet herkend.':
      'Pro lingua huius fasciculi nullus est index verborum clavium pro singularibus generibus datorum personalium. Formae cum numero probationis (BSN, IBAN, diploma) valent; verba ut "diagnosis" vel "suspectus" non agnoscuntur.',
  'Landpakketten voor identificatienummers':
      'Fasciculi nationales pro numeris identitatis',
  'Nummers als het BSN of het PESEL zijn landgebonden. Heel Europa staat aan omdat de meeste van die nummers een controlegetal hebben: die aanzetten kost vrijwel geen valse meldingen. IBAN, e-mail, geheimen en paspoortstroken staan hier los van en worden altijd nagekeken.':
      'Numeri ut BSN Batavicus vel PESEL Polonicus ad nationes pertinent. Tota Europa activa est quia plerique horum numerorum numerum probationis habent: eos accendere fere nullas falsas denuntiationes constat. IBAN, epistulae electronicae, arcana et lineae diplomatum ab his separantur et semper examinantur.',
